package br.com.onda;
import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class TiktokPhotosTest {
 static final String ID="7704446235020627218",PAGE="https://www.tiktok.com/@onda/photo/"+ID,PHOTO="https://cdn.example.com/photo.jpeg",AUDIO="https://cdn.example.com/audio";
 static JSONObject post()throws Exception{return new JSONObject().put("id",ID).put("imagePost",new JSONObject().put("images",new JSONArray().put(new JSONObject().put("imageURL",new JSONObject().put("urlList",new JSONArray().put(PHOTO)))))).put("music",new JSONObject().put("playUrl",AUDIO));}
 static String html(JSONObject post)throws Exception{return "<script id='__UNIVERSAL_DATA_FOR_REHYDRATION__'>"+new JSONObject().put("__DEFAULT_SCOPE__",new JSONObject().put("webapp.reflow.video.detail",new JSONObject().put("statusCode",0).put("itemInfo",new JSONObject().put("itemStruct",post))))+"</script>";}
 static PublicMediaHttp.Page page(JSONObject post)throws Exception{return new PublicMediaHttp.Page(PAGE,"text/html",html(post).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void photoLinkIsDistinctFromVideoAndCleansTracking()throws Exception{assertEquals(ID,MediaLinks.photoId(PAGE+"?share=1"));assertEquals(PAGE,MediaLinks.resolve(PAGE+"?share=1"));assertEquals("",MediaLinks.videoId(PAGE));assertEquals("",MediaLinks.photoId("https://evil.example.com/@onda/photo/"+ID));assertEquals("",MediaLinks.photoId(PAGE+"/other"));String moved="Moved. <a href='"+PAGE+"?x=1'>redirect</a>";assertEquals(PAGE,MediaDownloads.shortTarget(new PublicMediaHttp.Page("https://vt.tiktok.com/ZSpMhBrxN/","text/html",moved.getBytes())));}
 @Test public void originalPhotoAndSoundtrackRemainWithOptionalMp4()throws Exception{YoutubeDownloads.Result result=TiktokPhotos.inspect(page(post()),new PublicMediaSession(),(url,ref)->new PublicMediaHttp.Page(url,"video/mp4",url.equals(PHOTO)?new byte[]{(byte)255,(byte)216,(byte)255,1}:new byte[]{'I','D','3',4}));assertEquals(3,result.options.size());assertEquals("jpg",result.options.get(0).extension);assertEquals("image/jpeg",result.options.get(0).mime);assertEquals("mp3",result.options.get(1).extension);for(int i=0;i<2;i++){YoutubeDownloads.Option o=result.options.get(i);assertTrue(o.original);assertEquals(PAGE,o.referer);assertFalse(o.photoVideo);}YoutubeDownloads.Option video=result.options.get(2);assertTrue(video.photoVideo);assertFalse(video.original);assertEquals("mp4",video.extension);assertEquals(PHOTO,video.first);assertEquals(AUDIO,video.second);}
 @Test public void rejectsAnotherPostPrivateAndRecommendations()throws Exception{for(JSONObject p:new JSONObject[]{post().put("id","7704446235020627219"),post().put("privateItem",true),post().put("isContentClassified",true)})try{TiktokPhotos.item(html(p),ID);fail();}catch(Exception expected){}try{TiktokPhotos.item("<a href='"+PHOTO+"'>recommendation</a>",ID);fail();}catch(Exception expected){assertTrue(expected.getMessage().contains("fotos"));}}
 @Test public void badMirrorFallsBackAndHtmlIsNeverAnImage()throws Exception{JSONObject p=post();p.remove("music");p.getJSONObject("imagePost").getJSONArray("images").getJSONObject(0).getJSONObject("imageURL").put("urlList",new JSONArray().put("https://cdn.example.com/blocked").put(PHOTO));int[] calls={0};YoutubeDownloads.Result result=TiktokPhotos.inspect(page(p),new PublicMediaSession(),(u,r)->new PublicMediaHttp.Page(u,"image/jpeg",calls[0]++==0?"<html>login</html>".getBytes():new byte[]{(byte)255,(byte)216,(byte)255}));assertEquals(2,calls[0]);assertEquals(PHOTO,result.options.get(0).first);}
 @Test public void missingImagesCanStillOfferPublicAudioButNotVideo()throws Exception{JSONObject p=post();p.getJSONObject("imagePost").put("images",new JSONArray());YoutubeDownloads.Result result=TiktokPhotos.inspect(page(p),new PublicMediaSession(),(u,r)->new PublicMediaHttp.Page(u,"video/mp4",new byte[]{'I','D','3'}));assertEquals(1,result.options.size());assertEquals("mp3",result.options.get(0).extension);}
 @Test public void noAccessibleFileReportsPhotoNotExpiredLink()throws Exception{try{TiktokPhotos.inspect(page(post()),new PublicMediaSession(),(u,r)->new PublicMediaHttp.Page(u,"image/jpeg","<html>login</html>".getBytes()));fail();}catch(Exception expected){assertTrue(expected.getMessage().contains("fotos com música"));assertFalse(expected.getMessage().contains("expirado"));}}
 @Test public void imageHeadersAreCheckedIndependentlyOfMime(){assertEquals("",TiktokPhotos.imageExtension("<html>login</html>".getBytes()));assertEquals("png",TiktokPhotos.imageExtension(new byte[]{(byte)137,'P','N','G',13,10,26,10}));assertEquals("webp",TiktokPhotos.imageExtension(new byte[]{'R','I','F','F',0,0,0,0,'W','E','B','P'}));}
}
